import{_ as i,o as a,c as t,a3 as r}from"./chunks/framework.DjfA6S92.js";const _=JSON.parse('{"title":"Interview Compass 指引","description":"","frontmatter":{"title":"Interview Compass 指引"},"headers":[],"relativePath":"guide/interview-compass.md","filePath":"guide/interview-compass.md"}'),s={name:"guide/interview-compass.md"};function o(n,e,l,p,m,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="interview-compass" tabindex="-1">Interview Compass <a class="header-anchor" href="#interview-compass" aria-label="Permalink to &quot;Interview Compass&quot;">​</a></h1><p><a href="https://liyuk.github.io/interview-compass/" target="_blank" rel="noreferrer">Interview Compass</a> 是一份面向候选人、面试官和管理者的双语面试与晋升参考。它帮助你理解岗位目标、问题意图和可观察的证据，适合把本书中的知识准备延伸到面试表达、面试设计或晋升复盘。</p><h2 id="怎么开始" tabindex="-1">怎么开始 <a class="header-anchor" href="#怎么开始" aria-label="Permalink to &quot;怎么开始&quot;">​</a></h2><ol><li>先按目标选择路径：外部面试、校招、面试官设计、晋升或自我复盘。</li><li>选择工程方向和职责阶段，浏览对应的问题；不确定时可以先看完整问题库。</li><li>阅读每道题的考察意图和观察信号，用自己的具体经历说明背景、职责、判断、行动和结果。</li><li>面试官可以用问题意图和上下文追问来校准判断，不把信号当成机械打分表。</li></ol><p>它提供分析思路，不提供标准答案，也不会自动给人打分。题目页可以生成分析提示词，供你自行复制到选择的外部 AI 工具中。</p><ul><li><a href="https://liyuk.github.io/interview-compass/" target="_blank" rel="noreferrer">打开 Interview Compass 中文站</a></li><li><a href="https://liyuk.github.io/interview-compass/en/" target="_blank" rel="noreferrer">Open Interview Compass in English</a></li><li><a href="https://github.com/Liyuk/interview-compass" target="_blank" rel="noreferrer">查看 Interview Compass 源码</a></li></ul>',6)])])}const u=i(s,[["render",o]]);export{_ as __pageData,u as default};
